/// @brief Enumeration for error code.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class tts_error_e {
  /// < Successful
  static const int TTS_ERROR_NONE = 0;

  /// < Out of Memory
  static const int TTS_ERROR_OUT_OF_MEMORY = -12;

  /// < I/O error
  static const int TTS_ERROR_IO_ERROR = -5;

  /// < Invalid parameter
  static const int TTS_ERROR_INVALID_PARAMETER = -22;

  /// < Network is down
  static const int TTS_ERROR_OUT_OF_NETWORK = -100;

  /// < No answer from the daemon
  static const int TTS_ERROR_TIMED_OUT = -1073741823;

  /// < Permission denied
  static const int TTS_ERROR_PERMISSION_DENIED = -13;

  /// < TTS NOT supported
  static const int TTS_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Invalid state
  static const int TTS_ERROR_INVALID_STATE = -49348607;

  /// < Invalid voice
  static const int TTS_ERROR_INVALID_VOICE = -49348606;

  /// < No available engine
  static const int TTS_ERROR_ENGINE_NOT_FOUND = -49348605;

  /// < Operation failed
  static const int TTS_ERROR_OPERATION_FAILED = -49348604;

  /// < Audio policy blocked
  static const int TTS_ERROR_AUDIO_POLICY_BLOCKED = -49348603;

  /// < Not supported feature of current engine @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
  static const int TTS_ERROR_NOT_SUPPORTED_FEATURE = -49348602;

  /// < Service reset @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
  static const int TTS_ERROR_SERVICE_RESET = -49348601;

  /// < Screen reader is off (Since 6.5)
  static const int TTS_ERROR_SCREEN_READER_OFF = -49348600;
}

/// @brief Enumeration for TTS mode.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class tts_mode_e {
  /// < Default mode for normal application
  static const int TTS_MODE_DEFAULT = 0;

  /// < Notification mode
  static const int TTS_MODE_NOTIFICATION = 1;

  /// < Accessibility mode
  static const int TTS_MODE_SCREEN_READER = 2;
}

/// @brief Enumeration for state.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class tts_state_e {
  /// < 'CREATED' state
  static const int TTS_STATE_CREATED = 0;

  /// < 'READY' state
  static const int TTS_STATE_READY = 1;

  /// < 'PLAYING' state
  static const int TTS_STATE_PLAYING = 2;

  /// < 'PAUSED' state
  static const int TTS_STATE_PAUSED = 3;
}

/// @brief Enumeration for service state.
/// @since_tizen 7.0
abstract class tts_service_state_e {
  /// < 'Ready' state
  static const int TTS_SERVICE_STATE_READY = 0;

  /// < 'Synthesizing' state
  static const int TTS_SERVICE_STATE_SYNTHESIZING = 1;

  /// < 'Playing' state
  static const int TTS_SERVICE_STATE_PLAYING = 2;
}

